item.command:
/opt/homebrew/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
const cli=path.resolve('scripts/check-staff-hub-llm-imports.mjs');
const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'independent-verify-')));
function check(files,status,offenders=[]){
  const app=path.join(root,'apps/staff-hub');
  fs.rmSync(app,{recursive:true,force:true}); fs.mkdirSync(app,{recursive:true});
  for(const [name,source] of Object.entries(files)){const p=path.join(app,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,source);}
  const r=spawnSync(process.execPath,[cli],{cwd:root,encoding:'utf8',timeout:10000});
  assert.ifError(r.error);assert.equal(r.signal,null);assert.equal(r.status,status);
  if(status===0){assert.equal(r.stdout,'OK\\n');assert.equal(r.stderr,'');}
  else {assert.equal(r.stdout,'');assert.deepEqual(r.stderr.trim().split('\\n').sort(),offenders.map(([f,m])=>path.join(app,f)+': '+m).sort());}
  console.log(JSON.stringify({files:Object.keys(files),exit:r.status,stdout:r.stdout,stderr:r.stderr}));
}
try {
check({'sample.mjs':\"import SDK from 'openai';\"},1,[['sample.mjs','openai']]);
check({'sample.cjs':\"const sdk = require('anthropic');\"},1,[['sample.cjs','anthropic']]);
} finally {fs.rmSync(root,{recursive:true,force:true});}
NODE"

